import {parseEpub,paginate} from './epub.js';
import * as Store from './store.js';
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => Array.from(root.querySelectorAll(selector));
const escapeHTML = (value='') => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4c3-1 5-1 8 1 3-2 5-2 8-1v15c-3-1-5-1-8 1-3-2-5-2-8-1V4Z M12 5v15',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bookOpen:'M3 4h6l3 2 3-2h6v15h-6l-3 2-3-2H3z M12 6v15',notes:'M5 3h14v18H5z M9 8h6 M9 12h6 M9 16h3',appearance:'M12 3a9 9 0 1 0 9 9c0-1-1-2-2-2h-2a2 2 0 0 1-2-2c0-1 1-2 1-3s-2-2-4-2Z M7 10h.01 M7 15h.01 M11 7h.01',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10.5a7.5 7.5 0 1 1-15 0 7.5 7.5 0 0 1 15 0',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',arrow:'M5 12h14 m-5-5 5 5-5 5',close:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',cloud:'M7 18H6a4 4 0 0 1-1-8 7 7 0 0 1 13-2 5 5 0 0 1 0 10h-1 M12 13v8 m-3-3 3 3 3-3',upload:'M12 16V3 m-5 5 5-5 5 5 M4 14v7h16v-7',bookmark:'M6 3h12v18l-6-4-6 4z',quote:'M4 12h5v7H3v-9c0-4 2-6 6-6 M15 12h5v7h-6v-9c0-4 2-6 6-6',sun:'M12 3v1 M12 20v1 M3 12h1 M20 12h1 m-3.6-6.4-.7.7 M6.3 17.7l-.7.7 m0-12.8.7.7 m11.4 11.4.7.7 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10',sparkle:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',more:'M5 12h.01 M12 12h.01 M19 12h.01',download:'M12 3v13 m-5-5 5 5 5-5 M4 16v5h16v-5',expand:'M4 9V4h5 M15 4h5v5 M20 15v5h-5 M9 20H4v-5',edit:'m15 4 5 5 M3 21l5-1L21 7l-5-5L3 15z',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',back:'M20 12H4 m6-6-6 6 6 6',sliders:'M4 7h9 M17 7h3 M4 17h3 M11 17h9 M13 4v6 M7 14v6',clock:'M12 7v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',single:'M6 3h12v18H6z',double:'M3 3h18v18H3z M12 3v18',folder:'M3 7V4h7l2 3h9v13H3V7Z'};
const icon=(name,cls='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="${cls}"><path d="${paths[name]||paths.book}"/></svg>`;
const actionButton=(action,name,label,extra='')=>`<button class="icon-button ${extra}" data-action="${action}" aria-label="${escapeHTML(label)}" title="${escapeHTML(label)}">${icon(name)}</button>`;
const catalog=[
{id:'alice',title:'Alice’s Adventures in Wonderland',shortTitle:'Alice’s Adventures in Wonderland',author:'Lewis Carroll',genre:'Fantasy',year:'1865'},
{id:'pride',title:'Pride and Prejudice',author:'Jane Austen',genre:'Romance',year:'1813'},
{id:'frankenstein',title:'Frankenstein',author:'Mary Shelley',genre:'Gothic fiction',year:'1818'},
{id:'sherlock',title:'The Adventures of Sherlock Holmes',author:'Arthur Conan Doyle',genre:'Mystery',year:'1892'},
{id:'treasure',title:'Treasure Island',author:'Robert Louis Stevenson',genre:'Adventure',year:'1883'},
{id:'time',title:'The Time Machine',author:'H. G. Wells',genre:'Science fiction',year:'1895'}
].map(book=>({...book,url:`./books/${book.id}.epub`,cover:`./covers/${book.id}.svg`,source:'demo'}));
let books=[...catalog];
let view='library',filter='all',sort='recent',layout='grid',search='';
let currentBook=null,pages=[],pageIndex=0,hudVisible=true,selectedRange=null,noteColor='amber',editingAnnotation=null;
let drawerTab='contents',previousFocus=null,toastTimeout,resizeTimeout,sensor=null,sensorLux=null,sensorMessage='';
let activeOpen=0;
const colorValues={amber:'#e5c16e',emerald:'#91bea5',sapphire:'#95b2dc',rose:'#d99fb5'};
const app=$('#app'),overlay=$('#overlay-root');
const percentage=id=>Math.round(Store.progress[id]?.percentage||0);
const bookCover=book=>book.cover||'./covers/time.svg';
const bookNotes=id=>Store.annotations.filter(a=>a.bookId===id);
const isSpread=()=>Store.preferences.spreadMode==='double'&&innerWidth>640;
const step=()=>isSpread()?2:1;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),3500);}
function storageWarning(){if(!Store.storageHealthy)toast('Device storage is unavailable. Changes may not survive closing this tab.');}
function resolvedTheme(){const p=Store.preferences;if(p.themeMode!=='auto-sensor')return p.themeMode;if(p.simulateLight)return p.lux<p.ambientLuxThreshold?'dark':'light';if(sensorLux!==null)return sensorLux<p.ambientLuxThreshold?'dark':'light';return matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';}
function applyPreferences(){const p=Store.preferences;document.body.dataset.theme=resolvedTheme();const s=document.documentElement.style;s.setProperty('--glass-blur',`${p.glassBlur}px`);s.setProperty('--glass-opacity',p.glassOpacity);const fonts={Lora:"'Lora',Georgia,serif",Georgia:'Georgia,serif','Plus Jakarta Sans':"'Plus Jakarta Sans',sans-serif",Merriweather:"'Merriweather',Georgia,serif",'JetBrains Mono':"'JetBrains Mono',monospace",'DM Sans':"'DM Sans',sans-serif",monospace:'ui-monospace,monospace'};s.setProperty('--reader-font',fonts[p.fontFamily]||fonts.Lora);s.setProperty('--reader-size',`${p.fontSize}px`);s.setProperty('--reader-line',p.lineHeight);s.setProperty('--reader-margin',`${p.margin}px`);$('meta[name="theme-color"]').content=resolvedTheme()==='dark'?'#11151e':'#f6f5f2';}
function manageSensor(){if(sensor){sensor.stop();sensor=null;}sensorLux=null;const p=Store.preferences;if(p.themeMode!=='auto-sensor'||p.simulateLight){applyPreferences();return;}if('AmbientLightSensor'in window){try{sensor=new window.AmbientLightSensor({frequency:1});sensor.addEventListener('reading',()=>{sensorLux=sensor.illuminance;applyPreferences();updateSensorLabel();});sensor.addEventListener('error',()=>{sensorMessage='Hardware sensor unavailable. Following your device theme.';sensorLux=null;applyPreferences();updateSensorLabel();});sensor.start();sensorMessage='Waiting for the device light sensor…';}catch{sensorMessage='Sensor access is unavailable. Following your device theme.';}}else sensorMessage='No hardware sensor detected. Following your device theme.';applyPreferences();updateSensorLabel();}
function updateSensorLabel(){const el=$('#sensor-state');if(el)el.textContent=Store.preferences.simulateLight?`Simulator active · ${Store.preferences.lux} lux · ${resolvedTheme()==='dark'?'Obsidian':'Paper'} theme`:sensorLux!==null?`Device sensor · ${Math.round(sensorLux)} lux`:sensorMessage||'Move the slider to simulate your surroundings.';}
function navItem(action,name,label,active,count=''){return `<button class="nav-item ${active?'active':''}" data-action="${action}" title="${label}" aria-label="${label}">${icon(name)}<span>${label}</span>${count!==''?`<span class="nav-count">${count}</span>`:''}</button>`;}
function shell(content){const reading=books.filter(b=>Store.progress[b.id]&&percentage(b.id)<100).length;return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#library" data-action="library" aria-label="LuminaGlass library"><div class="brand-symbol">${icon('bookOpen')}</div><div><span class="brand-name">LuminaGlass</span><span class="brand-sub">A space to get lost</span></div></a><div class="nav-label">Your reading room</div><nav class="nav-group" aria-label="Main navigation">${navItem('library','grid','My library',view==='library'&&filter==='all',books.length)}${navItem('reading','bookOpen','Reading now',view==='library'&&filter==='reading',reading||'')}${navItem('notes','notes','Notes & highlights',view==='notes')}</nav><div class="sidebar-separator"></div><nav class="nav-group" aria-label="Preferences">${navItem('appearance','appearance','Appearance',false)}${navItem('import','plus','Add a book',false)}</nav><div class="shelf-note">${icon('quote')}<p>“A reader lives a thousand lives before he dies.”</p><small>— George R. R. Martin</small></div><button class="local-status" data-action="status"><span class="status-dot"></span><span>Saved on this device ${icon('chevron')}</span></button></aside><main class="main"><header class="topbar"><div class="breadcrumb">Your space ${icon('chevron')}<span>${view==='notes'?'Notes & highlights':'My library'}</span></div><div class="topbar-right"><label class="search-field">${icon('search')}<input type="search" id="book-search" placeholder="Search your library" value="${escapeHTML(search)}" aria-label="Search your library"><kbd>⌘ K</kbd></label><button class="primary" data-action="import">${icon('plus')} Add a book</button></div></header>${content}</main></div>`;}
function latestBook(){return [...books].sort((a,b)=>(Store.progress[b.id]?.updatedAt||'').localeCompare(Store.progress[a.id]?.updatedAt||''))[0]||books[0];}
function hero(){const book=latestBook(),p=Store.progress[book.id];return `<section class="hero" aria-label="Your reading room"><div class="hero-copy"><div class="eyebrow">${icon('sparkle')} A moment, just for you</div><h1>A little quiet.<br>A <em>whole new world.</em></h1><p>Step out of the everyday. Your next chapter<br>is right where you left it.</p><div class="hero-foot">${icon('lock')} No accounts. No distractions. Just you and a good book.</div></div><div class="continue-card glass"><img class="mini-cover" src="${bookCover(book)}" alt="Cover of ${escapeHTML(book.title)}"><div class="continue-info"><div class="eyebrow">${p?'Pick up where you left off':'A good place to begin'}</div><h2>${escapeHTML(book.id==='alice'?'Down the rabbit hole':book.title)}</h2><p class="author">${escapeHTML(book.author)}</p><div class="progress-line"><span style="width:${percentage(book.id)}%"></span></div><div class="continue-progress"><span>${p?`${percentage(book.id)}% complete`:'A world of wonder awaits'}</span><span>${p?`Page ${p.pageIndex+1}`:book.year||'EPUB'}</span></div><button class="primary" data-action="open" data-id="${escapeHTML(book.id)}">${p?'Continue reading':'Start reading'} ${icon('arrow')}</button></div></div></section>`;}
function getFilteredBooks(){return books.filter(b=>(filter==='all'||filter==='reading'&&Store.progress[b.id]&&percentage(b.id)<100||filter==='finished'&&percentage(b.id)===100)&&`${b.title} ${b.author}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='title'?a.title.localeCompare(b.title):sort==='author'?a.author.localeCompare(b.author):(Store.progress[b.id]?.updatedAt||'').localeCompare(Store.progress[a.id]?.updatedAt||''));}
function cards(){const visible=getFilteredBooks();return visible.length?visible.map(book=>{const p=Store.progress[book.id];return `<article class="book-card"><button class="cover-button" data-action="open" data-id="${escapeHTML(book.id)}" aria-label="Read ${escapeHTML(book.title)}"><img class="book-cover" src="${bookCover(book)}" alt="${escapeHTML(book.title)} cover" loading="lazy"><span class="book-tag">EPUB</span><span class="cover-hover"><span>${icon('bookOpen')} ${p?'Keep reading':'Open book'}</span></span></button><button class="book-title" data-action="open" data-id="${escapeHTML(book.id)}">${escapeHTML(book.shortTitle||book.title)}</button><p class="book-author">${escapeHTML(book.author)}</p><div class="book-progress"><div class="progress-line"><span style="width:${percentage(book.id)}%"></span></div><div class="progress-meta"><span class="${p?'':'new'}">${p?percentage(book.id)===100?'Finished':`${percentage(book.id)}% complete`:'Not started'}</span><span>${p?`${p.chapterIndex+1} / ${book.chapters?.length||p.totalChapters||'—'} chapters`:book.genre||'Your collection'}</span></div></div></article>`;}).join(''):`<div class="empty-state">${icon('bookOpen')}<h2>${search?'No books found':filter==='finished'?'The last page is worth the wait.':'Your next chapter is waiting.'}</h2><p>${search?'Try a different title or author.':filter==='finished'?'Books you finish will find a home here.':'Open a book from your library and make a little time for yourself.'}</p><button class="secondary" data-action="all-books">Show all books ${icon('arrow')}</button></div>`;}
function renderLibrary(){view='library';currentBook=null;document.title='LuminaGlass — Your quiet corner';app.innerHTML=shell(`${hero()}<section aria-label="Book library"><div class="section-heading"><div><h2>Your library<span style="color:var(--accent)">.</span></h2><p>A small shelf. Endless possibilities.</p></div><span class="eyebrow">${books.length} books, all yours</span></div><div class="library-controls"><div class="tabs" role="tablist" aria-label="Filter books">${[['all','All books',books.length],['reading','Reading',books.filter(b=>Store.progress[b.id]&&percentage(b.id)<100).length],['finished','Finished',books.filter(b=>percentage(b.id)===100).length]].map(([key,label,count])=>`<button class="tab ${filter===key?'active':''}" data-action="filter" data-value="${key}" role="tab" aria-selected="${filter===key}">${label}<span class="tab-count">${count}</span></button>`).join('')}</div><div class="view-controls"><label><span class="sr-only">Sort books</span><select class="sort-select" id="sort-books"><option value="recent" ${sort==='recent'?'selected':''}>Recently read</option><option value="title" ${sort==='title'?'selected':''}>Title A–Z</option><option value="author" ${sort==='author'?'selected':''}>Author A–Z</option></select></label><div class="view-switch">${['grid','list'].map(mode=>`<button class="${layout===mode?'active':''}" data-action="layout" data-value="${mode}" aria-label="${mode} view" aria-pressed="${layout===mode}">${icon(mode)}</button>`).join('')}</div></div></div><div class="books-grid ${layout==='list'?'list-view':''}" id="book-grid">${cards()}</div></section><footer class="library-footer"><span>${icon('shield')} Your stories stay with you. Progress & notes are saved locally.</span><button data-action="source">${icon('cloud')} Demo collection ${icon('chevron')}</button></footer>`);}
function renderGrid(){const grid=$('#book-grid');if(grid){grid.className=`books-grid ${layout==='list'?'list-view':''}`;grid.innerHTML=cards();}}
function annotationHTML(a,compact=false){const book=books.find(b=>b.id===a.bookId);const chapter=book?.chapters?.[a.chapterIndex]?.title||`Chapter ${a.chapterIndex+1}`;return `<article class="${compact?'drawer-annotation':'annotation-card glass'}" style="--mark:${colorValues[a.color]||colorValues.sapphire}">${!compact?`<div class="eyebrow">${escapeHTML(book?.title||'Your book')}</div>`:''}${a.type==='bookmark'?`<div style="display:flex;gap:8px;align-items:center;margin:12px 0">${icon('bookmark')}<span class="serif">${escapeHTML(chapter)}</span></div>`:`<blockquote>${escapeHTML(a.selectedText)}</blockquote>`}${a.noteText?`<p class="note-text">${escapeHTML(a.noteText)}</p>`:''}<div class="annotation-footer"><span>${a.type==='bookmark'?'Bookmark':a.noteText?'Note & highlight':'Highlight'} · ${new Date(a.createdAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><span><button data-action="jump-annotation" data-id="${a.id}">Go to passage</button> ${actionButton(`edit-annotation`,'edit','Edit annotation').replace('data-action="edit-annotation"',`data-action="edit-annotation" data-id="${a.id}"`)}</span></div></article>`;}
function renderNotes(){view='notes';currentBook=null;document.title='Notes & highlights — LuminaGlass';app.innerHTML=shell(`<section class="notes-page"><div class="section-heading"><div><h2>The words that stay.</h2><p>${Store.annotations.length} saved ${Store.annotations.length===1?'moment':'moments'} from your reading life.</p></div><button class="secondary" data-action="export-notes">${icon('download')} Export notes</button></div><div class="annotation-grid">${Store.annotations.length?[...Store.annotations].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(a=>annotationHTML(a)).join(''):`<div class="empty-state">${icon('quote')}<h2>Keep a little of what moves you.</h2><p>Select a passage while reading to add a highlight or personal note. Bookmark a page to return to it later.</p><button class="primary" data-action="library">Find your next read ${icon('arrow')}</button></div>`}</div></section>`);}
async function ensureBook(id){let book=books.find(b=>b.id===id);if(!book)throw new Error('This book is no longer available in the library.');if(book.chapters)return book;const response=await fetch(book.url);if(!response.ok)throw new Error('This book could not be loaded. Please try again.');const parsed=await parseEpub(await response.arrayBuffer(),book.title);book={...book,...parsed,title:book.title,author:book.author};books=books.map(b=>b.id===id?book:b);await Store.dbPut('books',book);return book;}
function pageCapacity(){const p=Store.preferences;const width=Math.min(isSpread()?((innerWidth-180)/2):innerWidth-140,isSpread()?610:750);const contentWidth=Math.max(220,width-2*(innerWidth<=640?25:p.margin));const lines=Math.max(12,Math.floor(Math.min(600,Math.max(340,innerHeight-210))/(p.fontSize*p.lineHeight)));const charWidth=['monospace','JetBrains Mono'].includes(p.fontFamily)?.61:.51;return Math.max(450,Math.floor((contentWidth/(p.fontSize*charWidth))*lines*.77));}
function reflow(anchor){if(!currentBook)return;anchor=anchor||pages[pageIndex]||{chapterIndex:0,start:0};pages=paginate(currentBook.chapters,pageCapacity());const index=pages.findIndex(p=>p.chapterIndex===anchor.chapterIndex&&(anchor.start??anchor.charOffset??0)>=p.start&&(anchor.start??anchor.charOffset??0)<p.end);pageIndex=index>=0?index:Math.min(pageIndex,pages.length-1);if(isSpread())pageIndex=Math.floor(pageIndex/2)*2;}
async function openBook(id,anchor=null){const request=++activeOpen;closeOverlay();removeSelection();toast('Opening your book…');try{const book=await ensureBook(id);if(request!==activeOpen)return;currentBook=book;view='reader';pageIndex=0;pages=[];const p=Store.progress[id];reflow(anchor||{chapterIndex:p?.chapterIndex||0,start:p?.charOffset||0});hudVisible=true;renderReader();persistPosition();window.scrollTo(0,0);$('#toast').classList.remove('visible');storageWarning();}catch(error){if(request===activeOpen)toast(error.message||'This book could not be opened.');}}
function hasBookmark(page){return Store.annotations.find(a=>a.bookId===currentBook.id&&a.type==='bookmark'&&a.chapterIndex===page.chapterIndex&&(a.charOffset??0)>=page.start&&(a.charOffset??0)<page.end);}
function markedText(page){const relevant=bookNotes(currentBook.id).filter(a=>a.type==='highlight'&&a.chapterIndex===page.chapterIndex&&a.startOffset<page.end&&a.endOffset>page.start);const boundaries=[page.start,page.end];for(const a of relevant){boundaries.push(Math.max(page.start,a.startOffset),Math.min(page.end,a.endOffset));}const points=[...new Set(boundaries)].sort((a,b)=>a-b);let html='';for(let i=0;i<points.length-1;i++){const start=points[i],end=points[i+1];const a=relevant.find(a=>a.startOffset<=start&&a.endOffset>=end);const text=escapeHTML(currentBook.chapters[page.chapterIndex].text.slice(start,end));html+=a?`<mark class="mark-${a.color}" data-annotation="${a.id}" title="${escapeHTML(a.noteText||'Edit highlight')}">${text}</mark>`:text;}return html;}
function pageHTML(index){const page=pages[index];if(!page)return `<article class="reading-page"><div class="empty-state">${icon('check')}<h2>A story, well spent.</h2><p>You’ve reached the end of this book.</p></div></article>`;const chapter=currentBook.chapters[page.chapterIndex],bookmarked=hasBookmark(page);return `<article class="reading-page" data-page="${index}" aria-label="Page ${index+1}"><div class="page-running-head">${escapeHTML(currentBook.title)}</div><button class="page-bookmark ${bookmarked?'active':''}" data-action="bookmark" data-index="${index}" aria-label="${bookmarked?'Remove bookmark':'Bookmark this page'}" title="${bookmarked?'Remove bookmark':'Bookmark this page'}">${icon('bookmark')}</button>${page.start===0?`<div class="page-chapter-label">Chapter ${page.chapterIndex+1}</div><h1>${escapeHTML(chapter.title.replace(/^CHAPTER\s+[IVXLC\d]+[.\s:–—-]*/i,'')||chapter.title)}</h1>`:''}<div class="page-text ${page.start===0?'chapter-start':''}" data-page="${index}" lang="${escapeHTML(currentBook.language||'en')}">${markedText(page)}</div><div class="page-number"><span>LUMINA EDITIONS</span><span>${index+1}</span><span>${escapeHTML(currentBook.author)}</span></div></article>`;}
function renderReader(animate=false){document.title=`${currentBook.title} — LuminaGlass`;app.innerHTML=`<main class="reader-shell ${hudVisible?'':'hud-hidden'}"><header class="reader-topbar glass"><div class="reader-book-info"><button class="reader-back" data-action="library" aria-label="Back to library">${icon('back')}<span>Library</span></button><div class="reader-book-title">${escapeHTML(currentBook.title)}<small>${escapeHTML(currentBook.author)}</small></div></div><div class="reader-actions">${actionButton('contents','list','Contents & annotations')}<button class="icon-button" data-action="appearance" aria-label="Reading appearance" title="Reading appearance">Aa</button>${actionButton('bookmark','bookmark','Bookmark current page',hasBookmark(pages[pageIndex])?'active':'')}${actionButton('fullscreen','expand','Toggle fullscreen','fullscreen-button')}${actionButton('toggle-hud','more','Hide reading controls')}</div></header><div class="reader-stage"><button class="page-turn" data-action="prev" aria-label="Previous page" ${pageIndex===0?'disabled':''}>${icon('left')}</button><div class="reader-pages ${isSpread()?'double':''} ${animate?`page-animation-${Store.preferences.pageAnimation}`:''}" id="reader-pages">${pageHTML(pageIndex)}${isSpread()?pageHTML(pageIndex+1):''}</div><button class="page-turn" data-action="next" aria-label="Next page" ${pageIndex+step()>=pages.length?'disabled':''}>${icon('chevron')}</button></div><p class="reading-help">${innerWidth<=640?'Swipe to turn the page':'← → to turn the page'} &nbsp; · &nbsp; Select a passage to make it yours &nbsp; · &nbsp; Tap the page margin for a quiet view</p><footer class="reader-bottom glass"><div class="reader-progress-labels"><span>${escapeHTML(currentBook.chapters[pages[pageIndex].chapterIndex].title)}</span><span>${readingPercentage()}%</span></div><label><span class="sr-only">Reading progress</span><input type="range" id="page-scrubber" min="0" max="${pages.length-1}" value="${pageIndex}" aria-label="Go to page"></label><div class="reader-bottom-hint"><span>Page ${pageIndex+1}${isSpread()&&pageIndex+1<pages.length?`–${pageIndex+2}`:''} of ${pages.length}</span><span>${Math.max(1,Math.ceil(pages.slice(pageIndex).reduce((n,p)=>n+p.text.split(/\s+/).length,0)/230))} min left in book · Saved locally</span></div></footer>${!hudVisible?`<button class="hud-reveal icon-button glass" data-action="toggle-hud" aria-label="Show reading controls">${icon('sliders')}</button>`:''}</main>`;}
function readingPercentage(){return pageIndex+step()>=pages.length?100:Math.round(pageIndex/Math.max(1,pages.length-1)*100);}
function persistPosition(){if(!currentBook||!pages[pageIndex])return;const p=pages[pageIndex];Store.saveProgress({bookId:currentBook.id,chapterIndex:p.chapterIndex,pageIndex,totalPages:pages.length,totalChapters:currentBook.chapters.length,percentage:pageIndex+step()>=pages.length?100:pageIndex/Math.max(1,pages.length-1)*100,charOffset:p.start,epubCfi:null});}
function goToPage(index){if(!currentBook)return;removeSelection();pageIndex=Math.max(0,Math.min(pages.length-1,Number(index)));if(isSpread())pageIndex=Math.floor(pageIndex/2)*2;renderReader(true);persistPosition();if(window.scrollY>130)window.scrollTo({top:0,behavior:'smooth'});}
function changePage(direction){const next=pageIndex+direction*step();if(next<0||next>=pages.length)return;goToPage(next);}
function toggleBookmark(index=pageIndex){if(!currentBook)return;const page=pages[index];const existing=hasBookmark(page);if(existing){Store.deleteAnnotation(existing.id);toast('Bookmark removed.');}else{Store.saveAnnotation({id:crypto.randomUUID(),bookId:currentBook.id,type:'bookmark',chapterIndex:page.chapterIndex,pageIndex:index,charOffset:page.start,color:'sapphire',createdAt:new Date().toISOString()});toast('A place to come back to. Bookmark saved.');}renderReader();storageWarning();}
function removeSelection(){selectedRange=null;$('.selection-popover')?.remove();window.getSelection()?.removeAllRanges();}
function selectionChanged(){if(view!=='reader'||overlay.firstElementChild)return;const selection=window.getSelection();if(!selection||selection.isCollapsed||!selection.rangeCount){$('.selection-popover')?.remove();return;}const range=selection.getRangeAt(0);const node=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;const textRoot=node.closest('.page-text');if(!textRoot||!textRoot.contains(range.startContainer)||!textRoot.contains(range.endContainer))return;const text=selection.toString();if(!text.trim()||text.length>10000)return;const before=range.cloneRange();before.selectNodeContents(textRoot);before.setEnd(range.startContainer,range.startOffset);const page=pages[Number(textRoot.dataset.page)];selectedRange={bookId:currentBook.id,chapterIndex:page.chapterIndex,pageIndex:Number(textRoot.dataset.page),startOffset:page.start+before.toString().length,endOffset:page.start+before.toString().length+text.length,selectedText:text,charOffset:page.start+before.toString().length};const rect=range.getBoundingClientRect();$('.selection-popover')?.remove();const pop=document.createElement('div');pop.className='selection-popover';pop.setAttribute('role','toolbar');pop.setAttribute('aria-label','Annotate selected text');pop.innerHTML=Object.keys(colorValues).map(color=>`<button class="color-button color-${color}" data-action="highlight" data-color="${color}" aria-label="Highlight ${color}" title="${color}"></button>`).join('')+`<button class="note-button" data-action="new-note">${icon('edit')} Add note</button>`;pop.style.left=`${Math.min(Math.max(12,rect.left+rect.width/2-125),innerWidth-270)}px`;pop.style.top=`${rect.top>65?rect.top-58:rect.bottom+10}px`;pop.addEventListener('pointerdown',e=>e.preventDefault());document.body.appendChild(pop);}
function saveHighlight(color,noteText=''){if(!selectedRange)return;const annotation={...selectedRange,id:crypto.randomUUID(),type:'highlight',color,noteText,createdAt:new Date().toISOString()};Store.saveAnnotation(annotation);removeSelection();closeOverlay();if(currentBook)renderReader();toast(noteText?'Your note is tucked safely into this chapter.':'A few words, kept for later. Highlight saved.');storageWarning();}
function showOverlay(html,drawer=false){previousFocus=document.activeElement;overlay.innerHTML=drawer?`<div class="drawer-backdrop" data-backdrop="true"><aside class="drawer" role="dialog" aria-modal="true" aria-label="${drawer==='appearance'?'Appearance studio':'Contents and annotations'}" tabindex="-1">${html}</aside></div>`:`<div class="overlay-backdrop" data-backdrop="true"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1">${html}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.dialog,.drawer',overlay)?.focus());}
function closeOverlay(){overlay.innerHTML='';document.body.style.overflow='';previousFocus?.focus?.();previousFocus=null;editingAnnotation=null;}
function dialogHeading(title){return `<div class="dialog-heading"><h2 id="dialog-title">${title}</h2>${actionButton('close','close','Close dialog')}</div>`;}
function importDialog(){showOverlay(`${dialogHeading('A new story awaits.')}<p>Bring your own book, or add one from a public library.</p><button class="upload-zone" data-action="choose-file" id="upload-zone">${icon('upload')}<b>Choose an EPUB file</b><small>or drop it here · DRM-free · up to 30 MB</small></button><div class="or-divider">OR ADD FROM A LINK</div><form id="url-form"><label class="field-label" for="book-url">Public EPUB or Supabase Storage URL</label><input class="text-input" id="book-url" type="url" required placeholder="https://…supabase.co/storage/v1/object/public/…"><p class="input-hint">Paste a public .epub URL, a catalog.json URL, or a public bucket URL with a catalog.json file. The server must allow browser downloads (CORS).</p><div class="form-error" id="import-error" role="alert"></div><button class="primary full" type="submit" id="url-submit">${icon('plus')} Add to my library</button></form><div class="privacy-note">${icon('lock')} Imported books stay on this device.</div>`);const zone=$('#upload-zone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files[0])importFile(e.dataTransfer.files[0]);});}
function importError(message){const el=$('#import-error');if(el)el.textContent=message;else toast(message);}
function importBusy(busy){$$('#url-submit,#upload-zone').forEach(b=>b.disabled=busy);if($('#url-submit'))$('#url-submit').innerHTML=busy?'Adding your story…':`${icon('plus')} Add to my library`;}
async function addParsed(buffer,filename,source='local'){const parsed=await parseEpub(buffer,filename.replace(/\.epub$/i,''));const digest=await crypto.subtle.digest('SHA-256',buffer);const id='import-'+Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('').slice(0,24);const existing=books.find(b=>b.id===id);if(existing)return {book:existing,duplicate:true};const book={...parsed,id,source,genre:'Your collection',cover:genericCover(parsed.title,parsed.author)};const saved=await Store.dbPut('books',book);if(!saved)throw new Error('Your device could not store this book. Free some browser storage and try again.');books.push(book);try{const channel=new BroadcastChannel('lumina-library');channel.postMessage({kind:'book-added',id});channel.close();}catch{}return {book,duplicate:false};}
function genericCover(title,author){const label=title.length>35?title.slice(0,32)+'…':title;const words=label.split(' ');let lines=[''];for(const word of words){if((lines[lines.length-1]+' '+word).length>17)lines.push(word);else lines[lines.length-1]+=(lines[lines.length-1]?' ':'')+word;}const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 440"><rect width="300" height="440" fill="#8189a7"/><rect x="22" y="22" width="256" height="396" fill="none" stroke="#e4daca" opacity=".5"/><circle cx="150" cy="280" r="76" fill="none" stroke="#e4daca" opacity=".5"/><path d="M100 300q25-12 50 0 25-12 50 0v-70q-25-12-50 0-25-12-50 0zm50-70v70" stroke="#e4daca" fill="none" stroke-width="2"/>${lines.map((line,i)=>`<text x="150" y="${85+i*32}" fill="#f8efde" font-family="Georgia,serif" font-size="26" text-anchor="middle">${escapeHTML(line)}</text>`).join('')}<text x="150" y="380" fill="#e6ddcb" font-family="Georgia,serif" font-size="12" text-anchor="middle">${escapeHTML(author.slice(0,35))}</text></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}
async function importFile(file){if(!file.name.toLowerCase().endsWith('.epub')){importError('Please choose a file with the .epub extension.');return;}if(file.size>30*1024*1024){importError('Please choose an EPUB smaller than 30 MB.');return;}importBusy(true);try{const result=await addParsed(await file.arrayBuffer(),file.name);closeOverlay();filter='all';search='';renderLibrary();toast(result.duplicate?'This story is already on your shelf.':`${result.book.title} is now on your shelf.`);}catch(e){importError(e.message||'This EPUB could not be imported.');}finally{importBusy(false);$('#epub-input').value='';}}
async function fetchLimited(url,type='buffer'){const parsedURL=new URL(url,location.href);if(!/^https?:$/.test(parsedURL.protocol))throw new Error('Please use a valid HTTPS URL.');const response=await fetch(parsedURL,{signal:AbortSignal.timeout(30000),credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw new Error(`The library returned HTTP ${response.status}. Check that the URL is public.`);if(Number(response.headers.get('content-length'))>30*1024*1024)throw new Error('This file exceeds the 30 MB limit.');if(!response.body)return type==='json'?response.json():response.arrayBuffer();const reader=response.body.getReader(),chunks=[];let length=0;while(true){const {done,value}=await reader.read();if(done)break;length+=value.byteLength;if(length>30*1024*1024){await reader.cancel();throw new Error('This file exceeds the 30 MB limit.');}chunks.push(value);}const bytes=new Uint8Array(length);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}return type==='json'?JSON.parse(new TextDecoder().decode(bytes)):bytes.buffer;}
async function importURL(url){importBusy(true);$('#import-error').textContent='';try{const input=new URL(url);if(!/^https?:$/.test(input.protocol))throw new Error('Use an HTTPS link to a public EPUB.');const isEPUB=/\.epub$/i.test(input.pathname);if(isEPUB){const result=await addParsed(await fetchLimited(url),decodeURIComponent(input.pathname.split('/').pop()),'supabase-url');closeOverlay();search='';filter='all';renderLibrary();toast(result.duplicate?'This story is already on your shelf.':'Your book is ready. Settle in.');}else{const manifestURL=/\.json$/i.test(input.pathname)?url:url.replace(/\/$/,'')+'/catalog.json';const manifest=await fetchLimited(manifestURL,'json');const entries=Array.isArray(manifest)?manifest:manifest.books;if(!Array.isArray(entries)||!entries.length)throw new Error('The catalog must contain a books array with public EPUB URLs.');if(entries.length>20)throw new Error('Please use a catalog with 20 books or fewer.');let added=0;for(const entry of entries){if(!entry.url)throw new Error('Each catalog entry needs a url field.');const resolved=new URL(entry.url,manifestURL).href;const result=await addParsed(await fetchLimited(resolved),entry.title||'Imported book','supabase-url');if(!result.duplicate)added++;}closeOverlay();search='';filter='all';renderLibrary();toast(`${added} ${added===1?'story':'stories'} added to your shelf.`);}}catch(e){importError(e.name==='TypeError'?'The URL could not be read. Check the public link and its CORS settings.':e.name==='TimeoutError'?'The download took too long. Please try again.':e.message||'This library could not be loaded.');}finally{importBusy(false);}}
function rangeSetting(key,label,min,max,stepValue,value,unit='',ends=[]){return `<div class="range-row"><label class="range-label" for="setting-${key}">${label}<output id="output-${key}">${value}${unit}</output></label><input id="setting-${key}" type="range" data-setting="${key}" min="${min}" max="${max}" step="${stepValue}" value="${value}" data-unit="${unit}">${ends.length?`<div class="range-ticks"><span>${ends[0]}</span><span>${ends[1]}</span></div>`:''}</div>`;}
function appearanceDialog(){const p=Store.preferences;showOverlay(`${dialogHeading('Make yourself at home.')}<div class="setting-section"><div class="setting-title">${icon('sun')} Reading atmosphere</div><div class="theme-options">${[['light','Paper','#f8f5ed','#56555c'],['sepia','Sepia','#eadfcb','#6a5a45'],['dark','Obsidian','#1b2231','#cbd3e6'],['auto-sensor','Auto','linear-gradient(135deg,#f4ecd9 50%,#263045 50%)','#8b9bc0']].map(([key,label,bg,color])=>`<button class="theme-option ${p.themeMode===key?'active':''}" data-action="set-theme" data-value="${key}" aria-pressed="${p.themeMode===key}"><span class="theme-swatch" style="background:${bg};color:${color}">${key==='auto-sensor'?icon('sun'):'Aa'}</span>${label}</button>`).join('')}</div><div id="sensor-controls" ${p.themeMode==='auto-sensor'?'':'hidden'}>${rangeSetting('lux','Simulate ambient light',0,500,1,p.lux,' lux',['Moonlit · 0','Sunlit · 500'])}<div class="sensor-status">${icon('info')}<span id="sensor-state"></span></div><button class="reset-button" data-action="device-light">Use device light / system theme</button></div></div><div class="setting-section"><div class="setting-title">${icon('sliders')} A touch of glass</div>${rangeSetting('glassBlur','Frosted blur',4,40,1,p.glassBlur,'px',['Clear','Dreamy'])}${rangeSetting('glassOpacity','Glass opacity',.35,.9,.01,p.glassOpacity,'',['Airy','Solid'])}<div style="margin-top:20px;padding:18px;border-radius:9px;background:linear-gradient(120deg,#a7b4dc,#e2c6ad);"><div class="glass" style="padding:15px;border-radius:7px;text-align:center;font:14px Fraunces,serif;color:var(--text)">A little window into your world.</div></div></div><div class="setting-section"><div class="setting-title">Aa &nbsp; Words, your way</div><label class="sr-only" for="font-family">Reading font</label><select id="font-family" class="font-select" data-setting="fontFamily">${[['Lora','Lora · Editorial serif'],['Merriweather','Merriweather · Classic serif'],['Plus Jakarta Sans','Plus Jakarta Sans · Modern sans'],['JetBrains Mono','JetBrains Mono · Quiet precision']].map(([v,l])=>`<option value="${v}" ${p.fontFamily===v?'selected':''}>${l}</option>`).join('')}</select>${rangeSetting('fontSize','Type size',14,28,1,p.fontSize,'px')}${rangeSetting('lineHeight','Line spacing',1.4,2.2,.1,p.lineHeight,'×')}${rangeSetting('margin','Page margins',20,85,1,p.margin,'px')}</div><div class="setting-section"><div class="setting-title">${icon('bookOpen')} Page layout</div><div class="segmented">${[['single','single','One page'],['double','double','Book spread']].map(([v,i,l])=>`<button class="${p.spreadMode===v?'active':''}" data-action="set-spread" data-value="${v}" aria-pressed="${p.spreadMode===v}">${icon(i)}${l}</button>`).join('')}</div><p class="input-hint" style="margin-top:9px">Book spread opens two pages on wider screens.</p><label class="field-label" for="page-animation">Page transition</label><select id="page-animation" class="font-select" data-setting="pageAnimation">${[['slide','Soft slide'],['flip','Gentle page turn'],['fade','Quiet fade']].map(([v,l])=>`<option value="${v}" ${p.pageAnimation===v?'selected':''}>${l}</option>`).join('')}</select></div><button class="reset-button" data-action="reset-appearance">Reset reading preferences</button>`,'appearance');updateSensorLabel();}
function contentsDialog(){if(!currentBook)return;showOverlay(`${dialogHeading('Between the pages.')}<div class="tabs" role="tablist" aria-label="Reader navigation">${[['contents','Contents'],['highlights','Highlights'],['bookmarks','Bookmarks']].map(([key,label])=>`<button class="tab ${drawerTab===key?'active':''}" data-action="drawer-tab" data-value="${key}" role="tab" aria-selected="${drawerTab===key}">${label}</button>`).join('')}</div><div id="drawer-content">${contentsBody()}</div>`,'contents');}
function contentsBody(){if(drawerTab==='contents')return `<nav class="toc-list" aria-label="Table of contents">${currentBook.chapters.map((c,i)=>`<button class="toc-item ${pages[pageIndex].chapterIndex===i?'active':''}" data-action="chapter" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span><span>${escapeHTML(c.title)}</span></button>`).join('')}</nav>`;const entries=bookNotes(currentBook.id).filter(a=>drawerTab==='bookmarks'?a.type==='bookmark':a.type==='highlight');return entries.length?entries.map(a=>annotationHTML(a,true)).join(''):`<div class="empty-state">${icon(drawerTab==='bookmarks'?'bookmark':'quote')}<p>${drawerTab==='bookmarks'?'Tap the ribbon on a page to keep your place.':'Select a few words in the book to add a highlight or note.'}</p></div>`;}
function noteDialog(annotation=null){const range=annotation||selectedRange;if(!range)return;editingAnnotation=annotation;noteColor=annotation?.color||'amber';const isBookmark=annotation?.type==='bookmark';showOverlay(`${dialogHeading(isBookmark?'A place to return to.':annotation?'A thought worth keeping.':'Leave a little thought.')}<p>${isBookmark?'This bookmark is saved on your device.':'Your notes are for you. Give these words a little meaning.'}</p>${!isBookmark?`<blockquote class="note-quote">${escapeHTML(range.selectedText)}</blockquote><div class="note-colors" aria-label="Highlight color">${Object.keys(colorValues).map(color=>`<button class="color-button color-${color} ${color===noteColor?'selected':''}" data-action="note-color" data-color="${color}" aria-label="${color}" aria-pressed="${color===noteColor}"></button>`).join('')}</div><form id="note-form"><label class="field-label" for="note-text">Your note</label><textarea id="note-text" class="text-input" placeholder="What does this passage bring to mind?" maxlength="10000">${escapeHTML(annotation?.noteText||'')}</textarea><div class="dialog-actions">${annotation?`<button type="button" class="secondary" data-action="delete-annotation" data-id="${annotation.id}">${icon('trash')} Delete</button>`:''}<button class="primary" type="submit">${icon('check')} Save ${annotation?'changes':'note'}</button></div></form>`:`<div class="dialog-actions"><button class="secondary" data-action="delete-annotation" data-id="${annotation.id}">${icon('trash')} Remove bookmark</button><button class="primary" data-action="jump-annotation" data-id="${annotation.id}">Return to page ${icon('arrow')}</button></div>`}`);editingAnnotation=annotation;}
function statusDialog(){showOverlay(`${dialogHeading('Your space. Your stories.')}<p>Your library lives in this browser. Progress, notes, and reading preferences sync instantly between tabs on this device.</p><div class="status-details"><div><span class="status-dot"></span> &nbsp; ${Store.storageHealthy?'Local storage connected':'Storage is currently unavailable'}</div><div>${books.length} books · ${Store.annotations.length} annotations</div><div>Device identity</div><div class="device-id">${escapeHTML(Store.deviceId)}</div></div><p class="input-hint" style="margin-top:17px">This is local saving, so clearing browser data also clears your library. Export notes to keep a separate copy. Other devices and browsers have their own libraries.</p><div class="dialog-actions"><button class="secondary" data-action="export-notes">${icon('download')} Export notes</button><button class="primary" data-action="close">Back to my space</button></div>`);}
function sourceDialog(){showOverlay(`${dialogHeading('A shelf of possibilities.')}<p>Six complete public-domain classics, bundled with LuminaGlass so you can start reading immediately.</p><div class="status-details">${icon('cloud')} &nbsp; Supabase Storage prototype<br><span style="color:var(--muted)">Local demo bucket · no cloud account connected</span></div><p class="input-hint" style="margin-top:17px">Connect your own public Supabase EPUB or catalog URL using “Add a book”. A catalog is a JSON file with a books array containing title and url fields. Only the books are downloaded; your reading data stays local.</p><p class="input-hint">Demo editions: Project Gutenberg (#11, #1342, #84, #1661, #120, #35). Public domain in the United States; check local copyright rules elsewhere. Original cover designs by LuminaGlass.</p><div class="dialog-actions"><button class="secondary" data-action="status" title="View local device status">${icon('shield')} My device</button><button class="secondary" data-action="download-catalog">${icon('download')} Sample catalog</button><button class="primary" data-action="import">${icon('plus')} Add your own</button></div>`);}
function download(filename,text,type='text/plain'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportNotes(){const data=Store.annotations.map(a=>({...a,bookTitle:books.find(b=>b.id===a.bookId)?.title||a.bookId}));download('luminaglass-notes.json',JSON.stringify({exportedAt:new Date().toISOString(),deviceId:Store.deviceId,annotations:data},null,2),'application/json');toast(`${data.length} saved moments exported.`);}
function updateSetting(key,value){const numeric=['glassBlur','glassOpacity','fontSize','lineHeight','margin','lux'];if(numeric.includes(key))value=Number(value);const change={[key]:value};if(key==='lux')change.simulateLight=true;Store.updatePreferences(change);applyPreferences();const output=$(`#output-${key}`);if(output)output.textContent=`${value}${$(`#setting-${key}`)?.dataset.unit||''}`;if(key==='lux'){manageSensor();updateSensorLabel();}if(['fontFamily','fontSize','lineHeight','margin'].includes(key)&&currentBook){reflow();renderReader();persistPosition();}}
async function handleAction(button,event){const action=button.dataset.action;const value=button.dataset.value,id=button.dataset.id;switch(action){
case 'library':event.preventDefault();activeOpen++;closeOverlay();removeSelection();filter='all';search='';renderLibrary();window.scrollTo(0,0);break;
case 'reading':filter='reading';renderLibrary();break;
case 'notes':closeOverlay();renderNotes();break;
case 'appearance':appearanceDialog();break;
case 'import':importDialog();break;
case 'close':closeOverlay();break;
case 'source':sourceDialog();break;
case 'status':statusDialog();break;
case 'open':await openBook(id);break;
case 'all-books':filter='all';search='';renderLibrary();break;
case 'filter':filter=value;renderLibrary();break;
case 'layout':layout=value;renderGrid();$$('.view-switch button').forEach(b=>{b.classList.toggle('active',b.dataset.value===layout);b.setAttribute('aria-pressed',b.dataset.value===layout);});break;
case 'choose-file':$('#epub-input').click();break;
case 'prev':changePage(-1);break;
case 'next':changePage(1);break;
case 'bookmark':toggleBookmark(Number(button.dataset.index??pageIndex));break;
case 'contents':contentsDialog();break;
case 'drawer-tab':drawerTab=value;$$('.drawer .tab').forEach(b=>{b.classList.toggle('active',b.dataset.value===value);b.setAttribute('aria-selected',b.dataset.value===value);});$('#drawer-content').innerHTML=contentsBody();break;
case 'chapter':{const index=pages.findIndex(p=>p.chapterIndex===Number(button.dataset.index));closeOverlay();goToPage(index);break;}
case 'toggle-hud':hudVisible=!hudVisible;renderReader();break;
case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Fullscreen is not available in this browser.');}break;
case 'highlight':saveHighlight(button.dataset.color);break;
case 'new-note':noteDialog();break;
case 'note-color':noteColor=button.dataset.color;$$('.note-colors button').forEach(b=>{b.classList.toggle('selected',b.dataset.color===noteColor);b.setAttribute('aria-pressed',b.dataset.color===noteColor);});break;
case 'edit-annotation':{const a=Store.annotations.find(a=>a.id===id);if(a)noteDialog(a);break;}
case 'delete-annotation':Store.deleteAnnotation(id);closeOverlay();if(currentBook)renderReader();else renderNotes();toast('Removed from your saved moments.');break;
case 'jump-annotation':{const a=Store.annotations.find(a=>a.id===id);if(a){closeOverlay();if(currentBook?.id===a.bookId){const index=pages.findIndex(p=>p.chapterIndex===a.chapterIndex&&(a.charOffset??a.startOffset??0)>=p.start&&(a.charOffset??a.startOffset??0)<p.end);goToPage(Math.max(0,index));}else await openBook(a.bookId,{chapterIndex:a.chapterIndex,start:a.charOffset??a.startOffset??0});}break;}
case 'set-theme':Store.updatePreferences({themeMode:value});applyPreferences();manageSensor();$$('.theme-option').forEach(b=>{b.classList.toggle('active',b.dataset.value===value);b.setAttribute('aria-pressed',b.dataset.value===value);});$('#sensor-controls').hidden=value!=='auto-sensor';break;
case 'set-spread':Store.updatePreferences({spreadMode:value});$$('.segmented button').forEach(b=>{b.classList.toggle('active',b.dataset.value===value);b.setAttribute('aria-pressed',b.dataset.value===value);});if(currentBook){reflow();renderReader();persistPosition();}break;
case 'device-light':Store.updatePreferences({simulateLight:false});manageSensor();break;
case 'reset-appearance':Store.updatePreferences({...Store.DEFAULTS,simulateLight:false});applyPreferences();manageSensor();if(currentBook){reflow();renderReader();persistPosition();}appearanceDialog();toast('A fresh start for your reading space.');break;
case 'export-notes':exportNotes();break;
case 'download-catalog':download('catalog.json',JSON.stringify({books:catalog.map(b=>({title:b.title,author:b.author,url:new URL(b.url,location.href).href}))},null,2),'application/json');break;
}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button){handleAction(button,event).catch(error=>toast(error.message||'Something went wrong. Please try again.'));return;}const mark=event.target.closest('[data-annotation]');if(mark&&window.getSelection()?.isCollapsed){const a=Store.annotations.find(a=>a.id===mark.dataset.annotation);if(a)noteDialog(a);return;}if(event.target.dataset.backdrop==='true'){closeOverlay();return;}if(event.target.closest('.reading-page')&&!event.target.closest('.page-text')&&window.getSelection()?.isCollapsed&&!overlay.firstChild){hudVisible=!hudVisible;renderReader();}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='book-search'){search=el.value;if(view!=='library'){view='library';renderLibrary();const searchInput=$('#book-search');searchInput.focus();}else renderGrid();}if(el.id==='page-scrubber'){const target=Number(el.value);const labels=$$('.reader-progress-labels span');if(labels[1])labels[1].textContent=`${Math.round(target/Math.max(1,pages.length-1)*100)}%`;el.setAttribute('aria-valuetext',`Page ${target+1} of ${pages.length}`);}if(el.dataset.setting)updateSetting(el.dataset.setting,el.value);});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='page-scrubber')goToPage(el.value);if(el.id==='sort-books'){sort=el.value;renderGrid();}if(el.id==='epub-input'&&el.files[0])importFile(el.files[0]);if(el.tagName==='SELECT'&&el.dataset.setting)updateSetting(el.dataset.setting,el.value);});
document.addEventListener('submit',event=>{if(event.target.id==='url-form'){event.preventDefault();importURL($('#book-url').value.trim());}if(event.target.id==='note-form'){event.preventDefault();const note=$('#note-text').value.trim();if(editingAnnotation){Store.saveAnnotation({...editingAnnotation,noteText:note,color:noteColor});closeOverlay();if(currentBook)renderReader();else renderNotes();toast('Your thought is saved.');}else saveHighlight(noteColor,note);}});
document.addEventListener('mouseup',()=>setTimeout(selectionChanged,10));
document.addEventListener('touchend',()=>setTimeout(selectionChanged,250));
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(overlay.firstChild)closeOverlay();else if(selectedRange)removeSelection();else if(currentBook){hudVisible=!hudVisible;renderReader();}return;}if(overlay.firstChild&&event.key==='Tab'){const panel=$('.dialog,.drawer');const focusable=$$('button:not(:disabled),input,select,textarea,a[href]',panel).filter(el=>el.getClientRects().length);if(!focusable.length){event.preventDefault();return;}const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel)){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}return;}if((event.metaKey||event.ctrlKey)&&event.key==='k'){event.preventDefault();if(!currentBook)$('#book-search')?.focus();return;}if(/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)||overlay.firstChild)return;if(currentBook){if(event.key==='ArrowRight'){event.preventDefault();changePage(1);}if(event.key==='ArrowLeft'){event.preventDefault();changePage(-1);}if(event.key.toLowerCase()==='b')toggleBookmark();}});
let touchStart=null;document.addEventListener('touchstart',e=>{if(view==='reader'&&!overlay.firstChild&&!e.target.closest('button,input'))touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};else touchStart=null;},{passive:true});document.addEventListener('touchend',e=>{if(!touchStart||!window.getSelection()?.isCollapsed)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.6)changePage(dx<0?1:-1);touchStart=null;},{passive:true});
window.addEventListener('resize',()=>{clearTimeout(resizeTimeout);resizeTimeout=setTimeout(()=>{if(currentBook){reflow();renderReader();persistPosition();}},200);});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>applyPreferences());
Store.onSync((kind,payload)=>{if(kind==='preferences'){applyPreferences();manageSensor();if(currentBook){reflow();renderReader();}}else if(kind==='progress'&&currentBook&&(!payload||payload.bookId===currentBook.id)){const saved=payload||Store.progress[currentBook.id];if(saved){reflow({chapterIndex:saved.chapterIndex,start:saved.charOffset||0});renderReader();}}else if(currentBook&&(kind.includes('annotation'))){renderReader();if($('#drawer-content'))$('#drawer-content').innerHTML=contentsBody();}else if(view==='notes'&&!overlay.firstChild)renderNotes();else if(view==='library'&&!overlay.firstChild&&document.activeElement?.id!=='book-search')renderLibrary();});
try{const libraryChannel=new BroadcastChannel('lumina-library');libraryChannel.onmessage=async()=>{const saved=await Store.dbGetAll('books');for(const book of saved)if(!books.some(b=>b.id===book.id))books.push(book);if(view==='library'&&!overlay.firstChild)renderLibrary();};}catch{}
async function init(){applyPreferences();app.innerHTML='<div class="loading-screen"><div class="spinner"></div><p>Making a little room for you…</p></div>';try{const response=await fetch('./storage/v1/object/public/lumina-library/catalog.json');if(response.ok){const manifest=await response.json();if(manifest.prototype&&Array.isArray(manifest.books)&&manifest.books.length)books=manifest.books;}}catch{/* Bundled metadata remains available if the prototype endpoint fails. */}await Store.hydrate();const saved=await Store.dbGetAll('books');for(const book of saved){const index=books.findIndex(b=>b.id===book.id);if(index>=0)books[index]={...books[index],...book};else books.push(book);}renderLibrary();manageSensor();storageWarning();}
init().catch(()=>{renderLibrary();toast('Some saved data could not be restored. You can still read the demo collection.');});
